public static class CombinedDistrictChecks {
static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
public static void RunCoast(string output)=>EditorCoroutineRunner.Begin(Guard(Coast(output),output));
public static void Run(string output)=>EditorCoroutineRunner.Begin(Guard(Check(output),output));
static IEnumerator Guard(IEnumerator check,string output){Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"Status.txt"),"RUNNING");while(true){bool more;try{more=check.MoveNext();}catch(Exception e){File.WriteAllText(Path.Combine(output,"Status.txt"),"FAIL "+e);(check as IDisposable)?.Dispose();yield break;}if(!more)break;yield return null;}File.WriteAllText(Path.Combine(output,"Status.txt"),"PASS connectivity, max four, selection/apply, merged L terrain, canonical heights, save/reopen, rectangle and strip groups");}
static IEnumerator Coast(string output){
var old=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();if(old)old.ReturnToMenu();yield return null;yield return null;
var menu=UnityEngine.Object.FindFirstObjectByType<MainMenuController>();menu.CreatePrototypeRegion("Combined Coastal District",RegionSize.Small,new RegionCreationSettings{seed=730421,terrainShape=RegionTerrainShape.Coast,climate=RegionClimate.Tropical,topography=0,rivers=0,streams=0});double deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(menu.IsOpeningRegion&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;
var view=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();Require(view&&!menu.IsOpeningRegion,"Coast creation");var ocean=view.Data.WaterBodies.First(b=>b.kind==WaterBodyKind.Ocean);int[] chosen=null;
bool Wet(int cell)=>ocean.Contains(new Vector2((cell%8+.5f)/8,(cell/8+.5f)/8));
for(int z=0;z<7&&chosen==null;z++)for(int x=0;x<7&&chosen==null;x++){var square=new[]{z*8+x,z*8+x+1,(z+1)*8+x,(z+1)*8+x+1};foreach(int missing in square){var cells=square.Where(c=>c!=missing).ToArray();if(Wet(missing)&&cells.Any(Wet)&&cells.Any(c=>!Wet(c))){chosen=cells;break;}}}
Require(chosen!=null,"Wet/dry L fixture");
var rig=view.GetComponentInChildren<CityForge.CameraSystem.CityForgeCameraController>();rig.SetHeading(45);var camera=rig.GetComponent<Camera>();Vector3 east=camera.transform.InverseTransformDirection(Vector3.right),north=camera.transform.InverseTransformDirection(Vector3.forward);
int coastal=view.Districts.Where(d=>d.waterFraction>.03f&&d.waterFraction<.95f).First().index;view.RequestDistrict(coastal);deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(view.DistrictLoading&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;
Require(view.ApprovedDistrict&&!view.DistrictLoading&&Mathf.Abs(Mathf.DeltaAngle(rig.CaptureRegionState().yaw,45))<.001f,"Single district preserves overview heading");Require(Vector3.Distance(east,camera.transform.InverseTransformDirection(Vector3.right))<.001f&&Vector3.Distance(north,camera.transform.InverseTransformDirection(Vector3.forward))<.001f,"East/north screen directions unchanged");yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"Single-Coast-Same-Heading.png"));yield return null;yield return null;
rig.SetHeading(90);view.ShowOverview();Require(Mathf.Abs(Mathf.DeltaAngle(rig.CaptureRegionState().yaw,90))<.001f,"Return preserves manually rotated heading");rig.SetHeading(45);yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"Region-East-Heading.png"));yield return null;yield return null;
view.CombineDistrictCells(chosen);view.RequestDistrict(chosen[1]);deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(view.DistrictLoading&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;var land=view.ApprovedDistrict;Require(land&&land.Water&&view.IsCombinedDistrict,"Merged coastal district and actual Crest");Require(Mathf.Abs(Mathf.DeltaAngle(rig.CaptureRegionState().yaw,45))<.001f,"Combined district retains overview heading");
var clip=land.GetComponentsInChildren<WaveHarmonic.Crest.ClipLodInput>().First(c=>c.name=="Coastal shoreline clipping");var texture=clip.GetData<WaveHarmonic.Crest.ClipTextureLodInputData>().Texture;var rt=RenderTexture.GetTemporary(256,256,0,RenderTextureFormat.ARGB32);var previous=RenderTexture.active;var readable=new Texture2D(256,256,TextureFormat.RGBA32,false,true);Graphics.Blit(texture,rt);RenderTexture.active=rt;readable.ReadPixels(new Rect(0,0,256,256),0,0);readable.Apply();RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);int excluded=0,water=0;
for(int z=2;z<254;z+=8)for(int x=2;x<254;x+=8){var p=land.Origin+new Vector2((x+.5f)/256,(z+.5f)/256)*land.Side;float mask=readable.GetPixel(x,z).r;if(!land.Contains(p)){Require(mask>.95f,"No ocean in excluded L corner");excluded++;}else if(ocean.Contains(p/view.MapSide+Vector2.one*.5f)&&land.Height(p)<view.SeaLevel-1){Require(mask<.05f,"Ocean retained within selected cells");water++;}}
UnityEngine.Object.Destroy(readable);Require(excluded>0&&water>0,"Actual water mask checked");foreach(var tree in land.CanonicalTreeInstances)Require(land.Contains(land.Origin+new Vector2(tree.position.x,tree.position.z)*land.Side),"Coastal trees confined");yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"Coastal-L-Playable.png"));yield return null;yield return null;
foreach(float heading in new[]{45f,135f,225f,315f}){
rig.SetHeading(heading);float until=Time.time+.6f;while(Time.time<until)yield return null;var capture=ScreenCapture.CaptureScreenshotAsTexture();float blue=0,green=0;int samples=0;
for(int z=1;z<32;z++)for(int x=1;x<32;x++){var p=land.Origin+new Vector2(x/32f,z/32f)*land.Side;if(!land.Contains(p)||land.ShoreDistance(p)>-8||!ocean.Contains(p/view.MapSide+Vector2.one*.5f))continue;var screen=camera.WorldToViewportPoint(new Vector3(p.x,view.SeaLevel,p.y));if(screen.z<=0||screen.x<.05f||screen.x>.84f||screen.y<.12f||screen.y>.8f)continue;var color=capture.GetPixel(Mathf.Clamp((int)(screen.x*capture.width),0,capture.width-1),Mathf.Clamp((int)(screen.y*capture.height),0,capture.height-1));blue+=color.b-color.r;green+=color.g-color.r;samples++;}
UnityEngine.Object.Destroy(capture);Require(samples>5&&blue/samples>.07f&&green/samples>.07f,"Ocean stays aqua rather than white at heading "+heading);File.AppendAllText(Path.Combine(output,"Water-Colors.txt"),heading+" samples="+samples+" blue-red="+blue/samples+" green-red="+green/samples+" smoothness="+land.Water.Surface.Material.GetFloat("_Crest_Smoothness")+"\n");ScreenCapture.CaptureScreenshot(Path.Combine(output,"Water-Heading-"+heading+".png"));yield return null;yield return null;
}
rig.SetHeading(45);
view.ShowOverview();yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"Coastal-L-Overview.png"));yield return null;yield return null;File.WriteAllText(Path.Combine(output,"Checks.txt"),"PASS actual coastal L-shaped native terrain, Crest ocean, GPU-read clipping mask excludes missing corner and retains selected water; canonical trees stay inside. Single and combined coast preserve overview heading; east/north screen directions match; return retains manual rotation. User saves never written.");
}
static IEnumerator Check(string output){
Require(DistrictConnections.Valid(new[]{0,1,8},8),"L valid");Require(DistrictConnections.Valid(new[]{0,1,2,3},8),"Four strip valid");Require(!DistrictConnections.Valid(new[]{7,8},8)&&!DistrictConnections.Valid(new[]{0,9},8)&&!DistrictConnections.Valid(new[]{0,1,2,3,4},8),"No wrap / diagonal / fifth cell");
var previous=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();if(previous)previous.ReturnToMenu();yield return null;yield return null;
var menu=UnityEngine.Object.FindFirstObjectByType<MainMenuController>();menu.CreatePrototypeRegion("Combined District Preview",RegionSize.Small,new RegionCreationSettings{seed=730421,topography=1,rivers=0,streams=0});double deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(menu.IsOpeningRegion&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;
var view=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();Require(view&&!menu.IsOpeningRegion,"Normal creation");var canonical=view.Data.Heights.Cast<float>().ToArray();var combiner=view.GetComponent<DistrictCombiner>();Require(combiner,"Combine controls");
combiner.SetActive(true);view.RequestDistrict(0);Require(view.SelectedDistrict==-1&&combiner.Selection.SequenceEqual(new[]{0}),"Combine click selects without entering");Require(!combiner.Select(9),"Diagonal blocked");Require(combiner.Select(1)&&combiner.Select(9)&&combiner.Select(8),"Four connected selected");Require(!combiner.Select(2)&&combiner.Selection.Length==4,"Fifth rejected");Require(combiner.Select(9),"Deselect to L");Require(!combiner.Select(0),"Cannot disconnect selection by removal");
yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"L-Selected.png"));yield return null;yield return null;combiner.Apply();Require(!combiner.Active&&view.CombinedDistricts.Length==1&&view.DistrictMembers(8).SequenceEqual(new[]{0,1,8}),"Apply creates one logical group");Require(canonical.SequenceEqual(view.Data.Heights.Cast<float>()),"Shared terrain never rewritten");
yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"L-Applied.png"));yield return null;yield return null;
string temp=Path.Combine(Application.temporaryCachePath,"combined-"+Guid.NewGuid().ToString("N")+".cfregion");
try {
SavedRegionStore.Write(SavedRegionStore.Capture(view),temp);var loaded=SavedRegionStore.Load(temp);Require(loaded.info.combinedDistricts[0].cells.SequenceEqual(new[]{0,1,8}),"Group metadata persists");view.RequestDistrict(8);deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(view.DistrictLoading&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;Require(view.ApprovedDistrict&&!view.DistrictLoading&&view.SelectedDistrict==0,"Any member opens same combined district");
var land=view.ApprovedDistrict;Require(Mathf.Approximately(land.Side,view.DistrictSide*2),"L covers two cells each way");var td=land.DisplayTerrain.terrainData;int r=td.holesResolution;Require(!td.IsHole(r/4,r/4)&&!td.IsHole(r*3/4,r/4)&&!td.IsHole(r/4,r*3/4)&&td.IsHole(r*3/4,r*3/4),"L excludes unselected quadrant");Require(land.Contains(land.Origin+Vector2.one*view.DistrictSide*.5f)&&!land.Contains(land.Origin+Vector2.one*view.DistrictSide*1.5f),"Playable footprint matches L");
foreach(var tree in land.CanonicalTreeInstances){var p=land.Origin+new Vector2(tree.position.x,tree.position.z)*land.Side;Require(land.Contains(p),"Native trees stay inside L");}
for(int z=0;z<9;z++)for(int x=0;x<9;x++){var p=land.Origin+new Vector2(x/8f,z/8f)*land.Side;float u=p.x/view.MapSide+.5f,v=p.y/view.MapSide+.5f;Require(Mathf.Abs(td.GetInterpolatedHeight(x/8f,z/8f)-view.Data.SmoothHeight(u,v)*td.size.y)<.2f,"Shared heights across merged cells");}
yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"L-Playable.png"));yield return null;yield return null;SavedRegionStore.Write(SavedRegionStore.Capture(view),temp);view.ReturnToMenu();yield return null;yield return null;
menu.OpenSavedRegion(SavedRegionStore.Load(temp).info);deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(menu.IsOpeningRegion&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;view=UnityEngine.Object.FindFirstObjectByType<PrototypeRegionView>();Require(view&&view.DistrictMembers(1).Length==3,"Normal reopen retains group");view.RequestDistrict(1);while(view.DistrictLoading&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;Require(view.ApprovedDistrict&&view.ApprovedDistrict.UsedSavedTerrain&&view.ActiveDistrictMembers.Length==3,"Merged cached terrain reload");view.ShowOverview();yield return null;yield return null;
combiner=view.GetComponent<DistrictCombiner>();combiner.SetActive(true);Require(combiner.Select(0)&&combiner.Selection.Length==3&&combiner.Select(9),"Existing group expands atomically to four");combiner.Apply();Require(view.DistrictMembers(9).Length==4,"Four-cell rectangle applied");view.RequestDistrict(9);deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(view.DistrictLoading&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;
Require(view.ApprovedDistrict&&view.ActiveDistrictMembers.Length==4,"Whole rectangle opens");td=view.ApprovedDistrict.DisplayTerrain.terrainData;r=td.holesResolution;Require(!td.IsHole(r/4,r/4)&&!td.IsHole(r*3/4,r*3/4),"Expanded rectangle restores formerly excluded corner");view.ShowOverview();yield return null;yield return null;
view.CombineDistrictCells(new[]{16,17,18,19});Require(view.DistrictMembers(19).Length==4,"Separate strip group");view.RequestDistrict(19);deadline=UnityEditor.EditorApplication.timeSinceStartup+240;while(view.DistrictLoading&&UnityEditor.EditorApplication.timeSinceStartup<deadline)yield return null;
land=view.ApprovedDistrict;Require(land&&view.ActiveDistrictMembers.Length==4&&Mathf.Approximately(land.Side,view.DistrictSide*4),"Four-cell strip loads");td=land.DisplayTerrain.terrainData;r=td.holesResolution;for(int cell=0;cell<4;cell++)Require(!td.IsHole((int)((cell+.5f)*r/4),r/8),"Every strip cell playable");Require(td.IsHole(r/2,r/2),"Strip excludes surrounding cells");foreach(var tree in land.CanonicalTreeInstances)Require(land.Contains(land.Origin+new Vector2(tree.position.x,tree.position.z)*land.Side),"Strip trees confined");
yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"Strip-Playable.png"));yield return null;yield return null;view.ShowOverview();yield return null;yield return null;
yield return null;yield return null;ScreenCapture.CaptureScreenshot(Path.Combine(output,"Multiple-Groups.png"));yield return null;yield return null;
File.WriteAllText(Path.Combine(output,"Checks.txt"),"PASS edge connectivity, no diagonal/wrap, four-cell limit, safe deselection, apply/active UI, gold union outlines, L-shaped loaded terrain/hole, native tree confinement, canonical shared heights unchanged, temporary metadata/cache save and normal reopen, existing-group expansion and separate strip. User save files never written.");
}finally{if(File.Exists(temp))File.Delete(temp);}
}
